#ifndef SPX_STUN_H
#define SPX_STUN_H
#include <stddef.h>
#include <stdint.h>
/**
 * Encode a 20-byte STUN Binding request into packet.
 * transaction must point to 12 caller-generated bytes and is copied into the request.
 * Both buffers remain owned by the caller; no I/O is performed.
 */
void stun_binding_request(uint8_t packet[20], const uint8_t transaction[12]);
/**
 * Validate a Binding success response against the 12-byte transaction ID.
 * packet contains length bytes. On success, write numeric host-order IPv4 and port
 * to ipv4/port and return 0. Return -1 for malformed, mismatched, unsupported, or
 * missing IPv4 XOR-MAPPED-ADDRESS data. Ignore outputs on failure.
 */
int stun_binding_response(const uint8_t *packet, size_t length, const uint8_t transaction[12],
                          uint32_t *ipv4, uint16_t *port);
typedef struct {
    void *context;
    /** Send one complete datagram to the configured STUN server: 0 success, nonzero failure.
     * packet is borrowed only until return; preserve the underlying UDP socket. */
    int (*send)(void *context, const uint8_t *packet, size_t length);
    /** Read at most capacity bytes, waiting no longer than timeout_ms. Return bytes
     * received, 0 for no packet, negative on error. Filter STUN source and preserve
     * unrelated peer data in the adapter; buffers are borrowed for this call. */
    int (*receive)(void *context, uint8_t *packet, size_t capacity, unsigned timeout_ms);
    /** Return monotonic milliseconds; the discovery deadlines depend on progress. */
    uint64_t (*now)(void *context);
    /** Fill the caller-owned data buffer with length random transaction-ID bytes. */
    void (*random)(void *context, void *data, size_t length);
} stun_io;
/**
 * Discover the mapped endpoint using the caller's persistent UDP socket callbacks.
 * io and its callbacks must be valid throughout this blocking call. Send up to
 * three copies of one transaction, with 500/1000/2000 ms response windows.
 * Return 0 with host-order ipv4/port, or -1 on send failure or exhausted retries.
 * The caller owns the socket and must keep it open for subsequent peer traffic.
 */
int stun_discover(const stun_io *io, uint32_t *ipv4, uint16_t *port);
#endif
